}

.dv-groupview.dv-active-group > .dv-tabs-and-actions-container .dv-tabs-container > .dv-tab.dv-inactive-tab,
.dv-groupview.dv-active-group > .dv-tabs-and-actions-container .dv-tabs-container > .dv-tab.dv-active-tab {
    background-color: inherit;
    color: inherit;
}
</style>
```

### Step 2: Update ui.js store to track current view

```js client/src/store/ui.js
// ... existing code ...

export const mutations = mutationTree(state, {
  // ... existing mutations ...

  setCurrentViewName(state, viewName) {
    state.currentViewName = viewName
  },

  // ... rest of mutations ...
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    // ... existing actions ...

    async loadView({ state }, view) {
      if (!state._desktopApi || !view?.desktop) return
      try {
        state._desktopApi.fromJSON(view.desktop)
        state.lastView = view

        // Notify Desktop component of current view name
        if (state._desktopApi.setCurrentViewName) {
          state._desktopApi.setCurrentViewName(view.name)
        }

        const project = $storex.projects.activeProject
        if (project) {
          $storex.ui.persistLastView({ project_id: project.project_id, view })
        }
        $storex.ui.addNotification({ text: `View "${view.name}" loaded` })
      } catch (ex) {
        console.error("Error loading view", ex)
      }
    },

    async saveView({ state }, name) {
      const project = $storex.projects.activeProject
      if (!project) return
      const projectApi = project.$api
      if (!projectApi) return
      const desktop = state._desktopApi ? state._desktopApi.toJSON() : {}
      const view = {
        name,
        project_id: project.project_id,
        desktop
      }
      await projectApi.views.save(view)
      await $storex.ui.loadViews()

      // Set current view name in Desktop component
      if (state._desktopApi.setCurrentViewName) {
        state._desktopApi.setCurrentViewName(name)
      }

      $storex.ui.persistLastView({ project_id: project.project_id, view })
      $storex.ui.addNotification({ text: `View "${name}" saved` })
      return view
    },

    async restoreLastView({ state }) {
      const project = $storex.projects.activeProject
      if (!project) return
      try {
        const key = `lastView_${project.project_id}`
        const stored = localStorage.getItem(key)
        if (!stored) return
        const { name } = JSON.parse(stored)
        const view = state.views.find(v => v.name === name)
        if (view) {
          await $storex.ui.loadView(view)
        }
      } catch (ex) {
        console.error("Error restoring last view", ex)
      }
    },

    // ... rest of actions ...
  }
)
```

## Key Changes Made

### Desktop.vue
1. **Added `onActiveProjectChange()` method** - Triggers when active project changes to load the appropriate view
2. **Added `autoSaveCurrentView()` method** - Saves current view automatically after layout modifications
3. **Added `debouncedAutoSave()` method** - Debounces auto-save to avoid excessive API calls
4. **Changed `onLayoutChange` handler** - Now calls debounced auto-save instead of direct save
5. **Added `currentViewName` data property** - Tracks which view is currently active
6. **Added watch on `activeProject`** - Detects project changes and loads appropriate view
7. **Exposed `setCurrentViewName()` method** - Allows UI store to notify Desktop of current view

### ui.js store
1. **Updated `loadView()` action** - Notifies Desktop component of the loaded view name
2. **Updated `saveView()` action** - Sets current view name in Desktop for subsequent auto-saves
3. **Enhanced `restoreLastView()` action** - Already handles restoring the last view per project

## Behavior

- **View Modifications**: When user adds/removes panels or rearranges layout, the view auto-saves after 1 second of inactivity
- **Project Switching**: When active project changes, the system automatically loads the last viewed layout for that project or initializes with default 'home' tab if no previous view exists
- **User Notifications**: Users receive feedback when views are loaded/saved

