        if (!projectApi) return
        const views = await projectApi.views.list()
        // Add timestamp if not present (for backwards compatibility)
        const viewsWithTimestamp = (views || []).map(v => ({
          ...v,
          timestamp: v.timestamp || Date.now()
        }))
        state.views = viewsWithTimestamp
      } catch (ex) {
        console.error("Error loading views", ex)
        state.views = []
      }
    },

    async saveView({ state }, name) {
      const project = $storex.projects.activeProject
      if (!project) return
      const projectApi = project.$api
      if (!projectApi) return
      const desktop = state._desktopApi ? state._desktopApi.toJSON() : {}

      // Include timestamp when saving view
      const view = {
        name,
        project_id: project.project_id,
        desktop,
        timestamp: Date.now()
      }

      await projectApi.views.save(view)
      await $storex.ui.loadViews()

      // Set current view name in Desktop component for subsequent auto-saves
      if (state._desktopApi?.setCurrentViewName) {
        state._desktopApi.setCurrentViewName(name)
      }
      state.currentViewName = name

      $storex.ui.addNotification({ text: `View "${name}" saved` })
      return view
    },

    resetDesktop({ state }) {
      const api = state._desktopApi
      if (!api) return
      const panelIds = api.panels.map(p => p.id)
      panelIds.forEach(id => {
        try {
          const panel = api.getPanel(id)
          if (panel) api.removePanel(panel)
        } catch (ex) {
          console.warn("Could not remove panel", id, ex)
        }
      })
      state.openApps = {}
    },

    async loadView({ state }, view) {
      if (!state._desktopApi || !view?.desktop) return
      try {
        state._desktopApi.fromJSON(view.desktop)
        state.lastView = view

        // Set current view name in Desktop component for auto-save tracking
        if (state._desktopApi?.setCurrentViewName) {
          state._desktopApi.setCurrentViewName(view.name)
        }
        state.currentViewName = view.name

        $storex.ui.addNotification({ text: `View "${view.name}" loaded` })
      } catch (ex) {
        console.error("Error loading view", ex)
      }
    },

    async deleteView({ state }, name) {
      const projectApi = $storex.projects.activeProject?.$api
      if (!projectApi) return
      await projectApi.views.delete(name)
      await $storex.ui.loadViews()

      // Clear last view if it matches the deleted one
      if (state.lastView?.name === name) {
        state.lastView = null
        state.currentViewName = null
      }

      $storex.ui.addNotification({ text: `View "${name}" deleted` })
    },

    async renameView({ state }, { oldName, newName }) {
      const projectApi = $storex.projects.activeProject?.$api
      if (!projectApi) return
      await projectApi.views.rename(oldName, newName)
      await $storex.ui.loadViews()

      // Update last view if it matches the renamed one
      if (state.lastView?.name === oldName) {
        state.lastView.name = newName
        state.currentViewName = newName
      }

      $storex.ui.addNotification({ text: `View renamed to "${newName}"` })
    },

    // Load the most recently modified view for the current project
    async restoreLatestView({ state }) {
      const project = $storex.projects.activeProject
      if (!project || !state.views.length) return

      try {
        // Find view with latest timestamp
        const latestView = state.views.reduce((latest, current) => 
          (current.timestamp || 0) > (latest.timestamp || 0) ? current : latest
        )

        if (latestView) {
          await $storex.ui.loadView(latestView)
        }
      } catch (ex) {
        console.error("Error restoring latest view", ex)
      }
    },

    // --- Project loading state actions ---

    setProjectLoading(_, isLoading) {
      $storex.ui.setProjectLoadingState({ isLoading })
    },

    updateProjectLoadingStep(_, { stepId, status, options = {} }) {
      window.dispatchEvent(new CustomEvent('project-loading-step', {
        detail: { stepId, status, options }
      }))
    },

    setProjectLoadingError(_, error) {
      $storex.ui.setProjectLoadingState({ error })
    }
  },
)
